local KTool = CS.Engine.Lib.KTool
local Singleton = import('Frame.Singleton')

---@class ActivityMournMgr
local ActivityMournMgr = Class('ActivityMournMgr',Singleton)
local ActivityMournDojo = import("Game.Dojo.ActivityMournDojo")
local CDTimerModule = CS.Engine.Modules.CDTimerModule.GetInstance()
local CountDownTime = 2592000

function ActivityMournMgr:__init()
	self:CleanCache()
end

function ActivityMournMgr:CleanCache()
	self.ActivityMournDojo = nil
	self.towerItemVos = nil
	self.towerLevelVos = nil
	self.plotVos = nil
end

function ActivityMournMgr:__delete()
	self:CleanCache()
end

function ActivityMournMgr:InitialDojo(data)
	if isNull(self.activityMournDojo) then
		self.activityMournDojo = ActivityMournDojo.New()
	end
	self.activityMournDojo:Fill(data)
end

function ActivityMournMgr:GetHomeDojo()
	return self.activityMournDojo
end

function ActivityMournMgr:UpdateBattleInfo(levelType, questId, battleInfo)
	questId = checkNumber(questId)
	if questId <= 0 then
		return
	end
	
	--爬塔
	if levelType == Constants.IDType.MournTower then
		CS.Engine.Lib.KCookie.Set("MournTowerQuestId", questId)
		self:GetHomeDojo():UpdateCurTowerId(questId)
		self:GetHomeDojo():UpdateMaxFloorId(questId)
	end
end

function ActivityMournMgr:GetMournBuffUpLevelConsume(buffId, level)
	if isNull(self.buffEffectVos) then
		self:InitBuffEffectVos()
	end
	
	if isNotNull(self.buffEffectVos[buffId]) and self.buffEffectVos[buffId][level] then
		return {
			goodsId = self.buffEffectVos[buffId][level].costItem,
			num = self.buffEffectVos[buffId][level].costItemNum,
		}
	end
	return {}
end

function ActivityMournMgr:GetBuffEffectVo(buffId, level)
	if isNull(self.buffEffectVos) then
		self:InitBuffEffectVos()
	end
	if isNotNull(self.buffEffectVos[buffId]) and self.buffEffectVos[buffId][level] then
		return self.buffEffectVos[buffId][level]
	end
	return nil
end

function ActivityMournMgr:GetLastPlotId(chapterId)
	if isNull(self.plotVos) then
		self:InitPlotVos()
	end
	
	if self.plotVos[chapterId] then
		return self.plotVos[chapterId][#self.plotVos[chapterId]].id
	end
	
	return nil
end

function ActivityMournMgr:GetPlotVos(chapterId)
	if isNull(self.plotVos) then
		self:InitPlotVos()
	end
	return self.plotVos[chapterId]
end

function ActivityMournMgr:InitPlotVos()
	self.plotVos = {}
	local allVos = CfUtils.GetCf(AutoIds.IdSetting6611, "MournPlotVo", true)
	for i, v in pairs(allVos) do
		if v.activetyId == self.activityData.activityContentId then
			if isNull(self.plotVos[v.chapter]) then
				self.plotVos[v.chapter] = {}
			end
			table.insert(self.plotVos[v.chapter],v)
		end
	end
end

function ActivityMournMgr:InitBuffEffectVos()
	local allVos = CfUtils.GetCf(AutoIds.IdSetting6610,"NightCatGoodsEffectVo",true)
	local data = {}
	for i, v in pairs(allVos) do
		if isNull(data[v.itemId]) then
			data[v.itemId] = {}
		end
		data[v.itemId][v.level] = v
	end
	self.buffEffectVos = data
end

function ActivityMournMgr:IsPassChapterNode(nodeId)
	local nodeData = self:GetChapterDataById(nodeId)
	local node = nodeData[#nodeData]
	local isPass = self:IsPassChapter(checkNumber(node.id))
	return isPass
end

function ActivityMournMgr:IsUnLockFirstChapter(questId)
	local data = self:GetChapterDataById(questId)
	local firstData = data[1]
	local isPass = self:IsPassChapter(checkNumber(firstData.unlockLevel))
	return isPass
end

function ActivityMournMgr:IsPassChapter(chapterId)
	return self.ActivityMournDojo:GetMainChapterId() >= checkNumber(chapterId)
end

function ActivityMournMgr:SaveActivityData(data)
	self.activityData = data
end

function ActivityMournMgr:GetActivityData()
	return self.activityData
end

function ActivityMournMgr:GetTowerLevelVos(activityId)
	local allVos = CfUtils.GetCf(AutoIds.IdSetting6614,"NightCatTowerQuestVo",true)
	if isNull(self.towerLevelVos) or table.count(self.towerLevelVos) <= 0 then
		self.towerLevelVos = {}
		for i, v in pairs(allVos) do
			if checkNumber(v.activeId) == activityId then
				table.insert(self.towerLevelVos,v)
			end
		end
	end
	return self.towerLevelVos
end

function ActivityMournMgr:GetTowerItemVos(activityId)
	local allVos = CfUtils.GetCf(AutoIds.IdSetting6609,"NightCatGoodsVo",true)
	if isNull(self.towerItemVos) or table.count(self.towerItemVos) <= 0 then
		self.towerItemVos = {}
		for i, v in pairs(allVos) do
			if checkNumber(v.activeId) == activityId then
				table.insert(self.towerItemVos,v)
			end
		end
	end
	return self.towerItemVos
end

function ActivityMournMgr:StartTimeDown()
	self:ReleaseTimer()
	self._timer = CDTimerModule:AddCD(1, function(count, id, Elapsed)
		if self.activityMournDojo.climbingResetNum >= self.activityMournDojo.limit then
			self.activityMournDojo.nextHpSeconds = 0
			self:ReleaseTimer()
			return
		end
		if self.activityMournDojo.nextHpSeconds < 0 then
			self.activityMournDojo.climbingResetNum = self.activityMournDojo.climbingResetNum + 1
			self.activityMournDojo.nextHpSeconds = self.activityMournDojo.recoverSeconds
			Events.Broadcast(Constants.EventNames.ActivityNightCatResetRecover)
		end
		self.activityMournDojo.nextHpSeconds = self.activityMournDojo.nextHpSeconds - Elapsed
	end, CountDownTime, true, true)
end

function ActivityMournMgr:ReleaseTimer()
	if self._timer then
		CDTimerModule:RemoveCD(self._timer)
		self._timer = nil
	end
end

function ActivityMournMgr:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return ActivityMournMgr